            std__io__print(kobel_concat3(KOBEL_STR("[*] "), tpath, KOBEL_STR(" ... ")));
            kobel_str test_name = str_base_name(str_strip_kb(tpath));
            kobel_str test_bin = kobel_concat3(KOBEL_STR("build/"), test_name, KOBEL_STR(".test_bin.exe"));
            compiler__driver__CompileOptions opts = (compiler__driver__CompileOptions){ KOBEL_STR(""), KOBEL_STR(""), KOBEL_STR(""), KOBEL_STR("cl"), false, std__collections__List_str_new(4), false };
            opts.input_path = tpath;
            opts.output_bin = test_bin;
            opts.c_compiler = cfg.cc;
            opts.quiet = true;
