kobel_str compiler__driver__c_compile_cmd(kobel_str c_path, kobel_str exe_path, kobel_str obj_path, kobel_str cc, bool quiet) {
    kobel_str host_cc = compiler__driver__resolve_host_cc(cc);
    bool is_path_with_spaces = (((str_contains(host_cc, KOBEL_STR("/")) || str_contains(host_cc, KOBEL_STR("\\"))) && (str_contains(host_cc, KOBEL_STR(" ")))) && !str_starts_with(host_cc, KOBEL_STR("\"")));
    kobel_str cc_bin = (is_path_with_spaces ? kobel_concat3(KOBEL_STR("\""), host_cc, KOBEL_STR("\"")) : host_cc);
    if (!std__sys__is_windows()) {
        kobel_str posix_exe = str_to_posix_path(exe_path);
        kobel_str posix_c = str_to_posix_path(c_path);
        kobel_str exe_arg = (str_contains(posix_exe, KOBEL_STR(" ")) ? kobel_concat3(KOBEL_STR("\""), posix_exe, KOBEL_STR("\"")) : posix_exe);
        kobel_str c_arg = (str_contains(posix_c, KOBEL_STR(" ")) ? kobel_concat3(KOBEL_STR("\""), posix_c, KOBEL_STR("\"")) : posix_c);
        kobel_str cmd = kobel_concat(kobel_concat5(KOBEL_STR("TMPDIR=\"build\" "), cc_bin, KOBEL_STR(" -O2 -o "), exe_arg, KOBEL_STR(" ")), c_arg);
        if (quiet) {
            cmd = kobel_concat(cmd, KOBEL_STR(" >/dev/null 2>&1"));
        }
        return cmd;
    }
    kobel_str win_exe = str_to_win_path(exe_path);
    kobel_str win_obj = str_to_win_path(obj_path);
    kobel_str win_c = str_to_win_path(c_path);
    kobel_str exe_arg = (str_contains(win_exe, KOBEL_STR(" ")) ? kobel_concat3(KOBEL_STR("\""), win_exe, KOBEL_STR("\"")) : win_exe);
    kobel_str obj_arg = (str_contains(win_obj, KOBEL_STR(" ")) ? kobel_concat3(KOBEL_STR("\""), win_obj, KOBEL_STR("\"")) : win_obj);
    kobel_str c_arg = (str_contains(win_c, KOBEL_STR(" ")) ? kobel_concat3(KOBEL_STR("\""), win_c, KOBEL_STR("\"")) : win_c);
    kobel_str tmp_setup = KOBEL_STR("set \"TMP=build\" && set \"TEMP=build\"");
    kobel_str vcvars_setup = KOBEL_STR("(where cl >nul 2>nul || if exist \"%ProgramFiles%\\Microsoft Visual Studio\\18\\Community\\VC\\Auxiliary\\Build\\vcvars64.bat\" call \"%ProgramFiles%\\Microsoft Visual Studio\\18\\Community\\VC\\Auxiliary\\Build\\vcvars64.bat\" >nul)");
    kobel_str cl_invoke = kobel_concat3(kobel_concat5(cc_bin, KOBEL_STR(" /nologo /O2 /std:c11 /Fe:"), exe_arg, KOBEL_STR(" /Fo:"), obj_arg), KOBEL_STR(" "), c_arg);
    kobel_str cmd = (compiler__driver__is_msvc_compiler(host_cc) ? ((kobel_streq(host_cc, KOBEL_STR("cl")) || kobel_streq(host_cc, KOBEL_STR("cl.exe"))) ? (std__sys__has_env(KOBEL_STR("VCINSTALLDIR")) ? kobel_concat3(tmp_setup, KOBEL_STR(" && "), cl_invoke) : kobel_concat5(tmp_setup, KOBEL_STR(" && "), vcvars_setup, KOBEL_STR(" && "), cl_invoke)) : kobel_concat3(tmp_setup, KOBEL_STR(" && "), cl_invoke)) : kobel_concat3(kobel_concat5(tmp_setup, KOBEL_STR(" && "), cc_bin, KOBEL_STR(" -O2 -o "), exe_arg), KOBEL_STR(" "), c_arg));
    if (quiet) {
        cmd = kobel_concat(cmd, KOBEL_STR(" >nul 2>nul"));
    }
    return cmd;
}

int32_t compiler__driver__CompileOptions_compile(compiler__driver__CompileOptions* self) {
    kobel_str input_path = self->input_path;
    kobel_str src = std__filesystem__File_read(input_path);
    if (str_empty(src)) {
        std__io__println(kobel_concat(KOBEL_STR("Error: Could not read source file or file is empty: "), input_path));
        return 1;
    }
    if (!self->quiet) {
        std__io__println(KOBEL_STR("[1/4] Loading modules (lex + parse)..."));
    }
    compiler__loader__ModuleLoader loader = compiler__loader__ModuleLoader_new(str_dir_of(input_path), self->extra_roots);
    if (compiler__loader__ModuleLoader_find_module(&loader, KOBEL_STR("std.fmt")).found) {
        compiler__loader__ModuleLoader_ensure_module(&loader, KOBEL_STR("std.fmt"), 0, 0, KOBEL_STR(""));
    }
    if (compiler__loader__ModuleLoader_find_module(&loader, KOBEL_STR("std.traits")).found) {
        compiler__loader__ModuleLoader_ensure_module(&loader, KOBEL_STR("std.traits"), 0, 0, KOBEL_STR(""));
    }
    if (compiler__loader__ModuleLoader_find_module(&loader, KOBEL_STR("std.string")).found) {
        compiler__loader__ModuleLoader_ensure_module(&loader, KOBEL_STR("std.string"), 0, 0, KOBEL_STR(""));
    }
    compiler__ast__node__AstNode* loaded_prog = compiler__loader__ModuleLoader_load_program(&loader, input_path, src);
    if (!std__collections__List_str_empty(&loader.errors)) {
        compiler__driver__print_diagnostics(loader.errors, input_path, &loader);
        return 1;
    }
    if (loaded_prog == NULL) {
        std__io__println(kobel_concat(KOBEL_STR("Error: Could not parse source file: "), input_path));
        return 1;
    }
    compiler__ast__node__AstNode* prog = loaded_prog;
    if (!self->quiet) {
        std__io__println(kobel_concat3(KOBEL_STR("  "), usz_to_str(compiler__loader__ModuleLoader_count(&loader)), KOBEL_STR(" module(s) loaded")));
    }
    if (!self->quiet) {
        std__io__println(KOBEL_STR("[2/4] Semantic analysis (declarations)..."));
    }
    compiler__sema__decl__pass__DeclPass decl_p = compiler__sema__decl__pass__DeclPass_new();
    compiler__sema__decl__pass__DeclPass_collect_program(&decl_p, prog);
    if (!std__collections__List_str_empty(&decl_p.errors)) {
        compiler__driver__print_diagnostics(decl_p.errors, input_path, &loader);
        return 1;
    }
    if (!self->quiet) {
        std__io__println(KOBEL_STR("[3/4] Semantic analysis (bodies)..."));
    }
    compiler__sema__body__pass__BodyPass body_p = compiler__sema__body__pass__BodyPass_new_2(decl_p.symtab, decl_p);
    compiler__sema__body__pass__BodyPass_check_program(&body_p, prog);
    if (!std__collections__List_str_empty(&body_p.errors)) {
        compiler__driver__print_diagnostics(body_p.errors, input_path, &loader);
        return 1;
    }
    compiler__sema__body__pass__BodyPass_lower_program(&body_p, prog);
    if (!self->quiet) {
        std__io__println(KOBEL_STR("[4/4] Generating C99 code..."));
    }
    compiler__codegen__c_codegen__CCodeGen codegen = (compiler__codegen__c_codegen__CCodeGen){ 0, std__collections__List_str_new(4), KOBEL_STR(""), KOBEL_STR(""), false, KOBEL_STR(""), KOBEL_STR(""), 0, std__collections__List_ptr_compiler__ast__node__AstNode_new(4), std__collections__List_usz_new(4), std__collections__List_bool_new(4), std__collections__List_usz_new(4) };
    kobel_str c_code = compiler__codegen__c_codegen__CCodeGen_gen_program(&codegen, prog);
    if (self->only_emit_c) {
        bool ok = std__filesystem__File_write(self->emit_c_path, c_code);
        if (!ok) {
            std__io__println(kobel_concat(KOBEL_STR("Error: Failed to write output file: "), self->emit_c_path));
            return 1;
        }
        if (!self->quiet) {
            std__io__println(kobel_concat(KOBEL_STR("[SUCCESS] C99 source written to "), self->emit_c_path));
        }
        return 0;
    }
    kobel_str out_path = self->output_bin;
    if (str_empty(out_path)) {
        out_path = kobel_concat(str_strip_kb(input_path), KOBEL_STR(".exe"));
    }
    kobel_str out_dir = str_dir_of(out_path);
    compiler__driver__ensure_dir(out_dir);
    compiler__driver__ensure_dir(KOBEL_STR("build"));
    kobel_str base_name = str_base_name(out_path);
    kobel_str c_tmp_path = kobel_concat3(KOBEL_STR("build/"), base_name, KOBEL_STR(".tmp.c"));
    kobel_str obj_tmp_path = kobel_concat3(KOBEL_STR("build/"), base_name, KOBEL_STR(".tmp.obj"));
    bool write_ok = std__filesystem__File_write(c_tmp_path, c_code);
    if (!write_ok) {
        std__io__println(kobel_concat(KOBEL_STR("Error: Failed to write temporary C file: "), c_tmp_path));
        return 1;
    }
    kobel_str host_cc = compiler__driver__resolve_host_cc(self->c_compiler);
    if (!self->quiet) {
        std__io__println(kobel_concat3(KOBEL_STR("[BUILDING] Invoking backend compiler ("), host_cc, KOBEL_STR(")...")));
    }
    kobel_str old_bin = kobel_concat(out_path, KOBEL_STR(".old"));
    if (std__filesystem__File_exists(out_path)) {
        compiler__driver__remove_file(old_bin);
        compiler__driver__move_file(out_path, old_bin);
    }
    kobel_str compile_cmd = compiler__driver__c_compile_cmd(c_tmp_path, out_path, obj_tmp_path, self->c_compiler, self->quiet);
    int32_t exit_code = std__sys__exec(compile_cmd);
    if (exit_code != 0) {
        if (std__filesystem__File_exists(old_bin) && !std__filesystem__File_exists(out_path)) {
            compiler__driver__move_file(old_bin, out_path);
        }
        std__io__println(kobel_concat5(KOBEL_STR("Error: Backend C compiler failed with exit code "), i32_to_str(exit_code), KOBEL_STR(": cmd was '"), compile_cmd, KOBEL_STR("'")));
        return exit_code;
    }
    if (!std__filesystem__File_exists(out_path)) {
        if (std__filesystem__File_exists(old_bin)) {
            compiler__driver__move_file(old_bin, out_path);
        }
        std__io__println(kobel_concat(KOBEL_STR("Error: Backend C compiler returned 0 but produced no executable: "), out_path));
        return 1;
    }
    compiler__driver__remove_file(c_tmp_path);
    compiler__driver__remove_file(obj_tmp_path);
    compiler__driver__remove_file(old_bin);
    if (!self->quiet) {
        std__io__println(kobel_concat(KOBEL_STR("[SUCCESS] Executable created: "), out_path));
    }
    return 0;
}

