lsp__analysis__AnalysisResult lsp__analysis__AnalysisResult_new(kobel_str path, kobel_str source, kobel_str workspace_root) {
    std__collections__List_lsp__analysis__LspDiagnostic diagnostics = std__collections__List_lsp__analysis__LspDiagnostic_new(4);
    compiler__lexer__Lexer lexer = compiler__lexer__Lexer_new(source);
    std__collections__List_compiler__lexer__Token tokens = compiler__lexer__Lexer_tokenize(&lexer);
    {
        size_t __for_n = std__collections__List_compiler__lexer__Token_count(&tokens);
        size_t __for_i = 0;
        while (__for_i < __for_n) {
            compiler__lexer__Token tok = std__collections__List_compiler__lexer__Token_at(&tokens, __for_i);
            if (tok.type == 72) {
                size_t l0 = ((tok.line > 0) ? (tok.line - 1) : 0);
                size_t c0 = ((tok.col > 0) ? (tok.col - 1) : 0);
                std__collections__List_lsp__analysis__LspDiagnostic_plus_assign(&diagnostics, (lsp__analysis__LspDiagnostic){ l0, c0, l0, (c0 + 1), 1, KOBEL_STR("Unrecognized character or syntax") });
            }
            __for_i = (__for_i + 1);
        }
    }
    compiler__parser__parser__Parser parser = compiler__parser__parser__Parser_new(tokens);
    compiler__ast__node__AstNode* prog = compiler__parser__parser__Parser_parse_program(&parser);
    if (parser.errors.len > 0) {
        {
            size_t __for_n = std__collections__List_str_count(&parser.errors);
            size_t __for_i = 0;
            while (__for_i < __for_n) {
                kobel_str err_msg = std__collections__List_str_at(&parser.errors, __for_i);
                std__collections__List_lsp__analysis__LspDiagnostic_plus_assign(&diagnostics, lsp__analysis__LspDiagnostic_new(err_msg, source));
                __for_i = (__for_i + 1);
            }
        }
        compiler__sema__symbol__SymbolTable empty_symtab = compiler__sema__symbol__SymbolTable_new();
        return (lsp__analysis__AnalysisResult){ diagnostics, empty_symtab, false, tokens };
    }
    kobel_str doc_mod = compiler__ast__decl__Program_declared_module_name(compiler__ast__node__AstNode_as_program(prog));
    if (doc_mod.len == 0) {
        doc_mod = str_path_to_module(str_base_name(path));
    }
    kobel_str entry_dir = str_dir_of(path);
    std__collections__List_str extra_roots = std__collections__List_str_new(4);
    if (workspace_root.len > 0) {
        std__collections__List_str_plus_assign(&extra_roots, workspace_root);
        std__collections__List_str_plus_assign(&extra_roots, str_join_path(workspace_root, KOBEL_STR("lib")));
        std__collections__List_str_plus_assign(&extra_roots, str_join_path(workspace_root, KOBEL_STR("src")));
    }
    compiler__loader__ModuleLoader loader = compiler__loader__ModuleLoader_new(entry_dir, extra_roots);
    if (compiler__loader__ModuleLoader_find_module(&loader, KOBEL_STR("std.fmt")).found) {
        compiler__loader__ModuleLoader_ensure_module(&loader, KOBEL_STR("std.fmt"), 0, 0, KOBEL_STR(""));
    }
    if (compiler__loader__ModuleLoader_find_module(&loader, KOBEL_STR("std.string")).found) {
        compiler__loader__ModuleLoader_ensure_module(&loader, KOBEL_STR("std.string"), 0, 0, KOBEL_STR(""));
    }
    compiler__ast__node__AstNode* full_prog = compiler__loader__ModuleLoader_load_program(&loader, path, source);
    if (loader.errors.len > 0) {
        {
            size_t __for_n = std__collections__List_str_count(&loader.errors);
            size_t __for_i = 0;
            while (__for_i < __for_n) {
                kobel_str err_msg = std__collections__List_str_at(&loader.errors, __for_i);
                if (lsp__analysis__is_error_for_doc(err_msg, doc_mod, path)) {
                    std__collections__List_lsp__analysis__LspDiagnostic_plus_assign(&diagnostics, lsp__analysis__LspDiagnostic_new(err_msg, source));
                }
                __for_i = (__for_i + 1);
            }
        }
    }
    if (full_prog != NULL) {
        compiler__sema__decl__pass__DeclPass decl_p = compiler__sema__decl__pass__DeclPass_new();
        compiler__sema__decl__pass__DeclPass_collect_program(&decl_p, full_prog);
        if (decl_p.errors.len > 0) {
            {
                size_t __for_n = std__collections__List_str_count(&decl_p.errors);
                size_t __for_i = 0;
                while (__for_i < __for_n) {
                    kobel_str err_msg = std__collections__List_str_at(&decl_p.errors, __for_i);
                    if (lsp__analysis__is_error_for_doc(err_msg, doc_mod, path)) {
                        std__collections__List_lsp__analysis__LspDiagnostic_plus_assign(&diagnostics, lsp__analysis__LspDiagnostic_new(err_msg, source));
                    }
                    __for_i = (__for_i + 1);
                }
            }
        }
        compiler__sema__body__pass__BodyPass body_p = compiler__sema__body__pass__BodyPass_new_2(decl_p.symtab, decl_p);
        compiler__sema__body__pass__BodyPass_check_program(&body_p, full_prog);
        if (body_p.errors.len > 0) {
            {
                size_t __for_n = std__collections__List_str_count(&body_p.errors);
                size_t __for_i = 0;
                while (__for_i < __for_n) {
                    kobel_str err_msg = std__collections__List_str_at(&body_p.errors, __for_i);
                    if (lsp__analysis__is_error_for_doc(err_msg, doc_mod, path)) {
                        std__collections__List_lsp__analysis__LspDiagnostic_plus_assign(&diagnostics, lsp__analysis__LspDiagnostic_new(err_msg, source));
                    }
                    __for_i = (__for_i + 1);
                }
            }
        }
        return (lsp__analysis__AnalysisResult){ diagnostics, decl_p.symtab, true, tokens };
    }
    compiler__sema__symbol__SymbolTable empty_symtab = compiler__sema__symbol__SymbolTable_new();
    return (lsp__analysis__AnalysisResult){ diagnostics, empty_symtab, false, tokens };
}

